# Construct the 21x21 result by filling the one-cell-expanded rectangle with 8,
# preserving the original 3 border and 8 interior.
grid = [[0]*21 for _ in range(21)]
for r in range(5,13):
    for c in range(4,12):
        grid[r][c] = 8
for r in range(6,12):
    for c in range(5,11):
        if r in (6,11) or c in (5,10):
            grid[r][c] = 3
        else:
            grid[r][c] = 8
assert len(grid) == 21 and all(len(row) == 21 for row in grid)
print('{"action":"submit","grid":' + str(grid).replace(' ', '') + '}')

